def is_balanced_ignoring_letters(s):
    pairs = {'(': ')', '[': ']', '{': '}'}
    closers = set(pairs.values())

    def helper(index, stack):
        if index == len(s):
            return not stack
        ch = s[index]
        if ch in pairs:
            return helper(index + 1, stack + [pairs[ch]])
        if ch in closers:
            if not stack or stack[-1] != ch:
                return False
            return helper(index + 1, stack[:-1])
        return helper(index + 1, stack)

    return helper(0, [])

