def reverse_vowels(s):
    vowels = set('aeiouAEIOU')
    vowel_chars = [c for c in s if c in vowels]
    chars = list(s)
    vi = len(vowel_chars) - 1
    for i, c in enumerate(chars):
        if c in vowels:
            chars[i] = vowel_chars[vi]
            vi -= 1
    return ''.join(chars)

