def justify_line(words, width):
    if len(words) == 1:
        return words[0] + ' ' * (width - len(words[0]))

    def helper(ws, remaining_gaps, remaining_spaces):
        if len(ws) == 1:
            return ws[0]
        space, extra = divmod(remaining_spaces, remaining_gaps)
        sep = ' ' * (space + (1 if extra > 0 else 0))
        rest_spaces = remaining_spaces - len(sep)
        return ws[0] + sep + helper(ws[1:], remaining_gaps - 1, rest_spaces)

    total_letters = sum(len(w) for w in words)
    return helper(words, len(words) - 1, width - total_letters)

