def add_minutes_to_time(time_str, minutes):
    parts = time_str.split(':')
    base_minutes = int(parts[0]) * 60 + int(parts[1])
    total = base_minutes + minutes
    while total < 0:
        total += 1440
    total %= 1440
    hour = total // 60
    minute = total % 60
    return str(hour).zfill(2) + ':' + str(minute).zfill(2)

def to_24_hour(time_str):
    hm, period = time_str.split()
    hour_str, minute_str = hm.split(':')
    hour = int(hour_str)
    if period == 'AM':
        hour = 0 if hour == 12 else hour
    else:
        hour = 12 if hour == 12 else hour + 12
    return str(hour).zfill(2) + ':' + minute_str

